function giftThanksLines(group, name, farm) {
 const pool=GIFT_THANKS[group];
 const decks=farm.giftThanksDecks??={};
 let deck=decks[group];
 if(!Array.isArray(deck)||!deck.length){
  deck=decks[group]=pool.map((_,i)=>i);
  for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}
 }
 return pool[deck.pop()].map((line,i)=>(i%2?'':'>')+line.replace('#',name));
}
